using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Observer.Linear;

internal sealed class GainRayAdaptiveDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Sharp native adaptive gain-ray capacity", H("Sharp native adaptive gain-ray capacity"), Blocks(Paragraph(Text("Fix d and a history length n at most d+1. Evaluation at the full set of original clocks 0 through d is a linear equivalence on the d+1 ordinary coefficients. The fiber coordinates are x,r,delta and the d+1-n remaining gain values at clocks n through d. Thus when n=d+1 there are exactly the three source-and-drift coordinates and no free gain coordinates.")),
            Paragraph(Text("The positive denominator is D=x+r. At a prefix clock i the prescribed numerator gain value is (y_i-delta)D when i is even and (y_i-delta)(1+xr) when i is odd. At each remaining clock it is D times the free gain value. Inverting full-clock evaluation gives the numerator coefficients B. The original whole gain has coefficients B/D, with arbitrary actual degree, signs and roots.")),
            Paragraph(Text("The polynomial substitution sends x,r to themselves, coefficients to B and drift to D delta. Every positive chart point is in its rational image: encode its coefficient vector divided by D and its drift divided by D. This proves nonzero pullback by polynomial identity on the positive x,r chart, rather than using ambient nullity as evidence about a prescribed fiber.")),
            Paragraph(Text("Currying the joint polynomial into fiber variables with polynomial history coefficients yields a nonzero coefficient q(y). If q(y) is nonzero, specialization to that exact history is a nonzero polynomial in the remaining fiber variables.")),
            Describe.Lean(DescribeId.Create("gain-ray-gainrayfiber-clockequiv"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.clockEquiv"),
                H("Full-clock interpolation equivalence"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The ordinary coefficient vector and its values at clocks 0,...,d are linearly equivalent."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("gain-ray-gainrayfiber-fiberbeta"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.fiberBeta"),
                H("Original whole gain on a fiber"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The numerator coefficients divided by the evaluated positive denominator x+r."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("gain-ray-gainrayfiber-fiberworld"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.fiberWorld"),
                H("Legal compatible whole world"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Positive x,r and a nonzero fiberBeta give the original legal source chart, whole gain and drift."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("gain-ray-gainrayfiber-eval-fiber-specialize"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.eval_fiber_specialize"),
                H("Exact specialization at a prescribed history"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Evaluating fiberSpecialize Q y at f equals evaluating Q at the joint coordinates (f,y)."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gain-ray-gainrayfiber-fiber-nonzero-coefficient"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.fiber_nonzero_coefficient"),
                H("A nonzero coefficient separates exceptional histories"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every nonzero joint polynomial Q, some nonzero history polynomial q makes fiberSpecialize Q y nonzero whenever q(y) is nonzero."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gain-ray-gainrayfiber-fiber-beta-nonzero"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.fiber_beta_nonzero"),
                H("Nonempty legal fibers at every history"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For 1<=n<=d+1 and positive x,r, choosing a drift different from the initial history value makes the whole fiber gain nonzero. This gives a point in every compatible fiber."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gain-ray-gainrayfiber-fiber-world-prefix"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.fiber_world_prefix"),
                H("Literal pure-J prefix equality"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every legal fiber point and every i<n, the original read at clock i on J repeated n-1 times equals y_i. No reindexing or skipped observation is used."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gain-ray-gainrayfiber-fiber-coordinates-cover"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.fiber_coordinates_cover"),
                H("Coverage of every original chart world"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Encoding every positive-chart source, every whole coefficient vector and every drift reconstructs that same coefficient vector. The tail coordinates are its remaining fixed-clock gain values."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gain-ray-gainrayfiber-eval-fiber-pullback"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.eval_fiber_pullback"),
                H("Exact denominator-cleared substitution"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The polynomial pullback evaluates at the same x,r, numerator coefficient vector B and drift D delta."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gain-ray-gainrayfiber-fiber-pullback-nonzero"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.fiber_pullback_nonzero"),
                H("Dominance of actual history coordinates"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every nonzero chart polynomial p and n<=d+1, its polynomial pullback is nonzero. The proof uses rational coverage of the full positive chart, including n=d+1."))), DescribeRole.Theorem),
Paragraph(Text("Let s be any countable set of word-matrix pairs, each containing M and taking at most 2(d+1) initial-inclusive reads. For each 1<=n<=d+1, short_history_completion constructs one nonzero history polynomial q_c for every pair c. The exceptional set E_n is the union of their zero sets. Every y outside E_n has one legal original world with exactly that pure-J prefix and no successful pair from s on its own word.")),
            Paragraph(Text("The mixed-word obstruction and the pure-M endpoint obstruction supply a nonzero chart wedge for every pair successful somewhere. A pair successful nowhere uses the constant polynomial one. Simultaneously scaling gain and drift by a nonzero number preserves success, so the denominator-cleared fiber substitution respects every successful world. Both positive and negative success scales remain admitted.")),
            Paragraph(Text("The full compatible fiber has x,r positive and a nonzero numerator coefficient vector. It is open. It is nonempty for every y: set x=r=1 and choose delta different from y_0. Countably many nonzero specialized polynomial zero sets cannot cover this nonempty open fiber. The proof applies the existing polynomial nullity theorem inside this prescribed fiber and positivity of volume on a nonempty open set. It assumes no regularity of a protocol, branch or selector.")),
            Describe.Lean(DescribeId.Create("gain-ray-gainraycompletion-fiberdomain"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.fiberDomain"),
                H("Full legal compatible fiber"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The source coordinates are positive and the whole numerator coefficient vector is nonzero. No individual coefficient or gain sample is constrained."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("gain-ray-gainraycompletion-exceptionalhistories"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.exceptionalHistories"),
                H("Countable algebraic exceptional histories"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For a countable index family q, this is the union of the zero sets of its history polynomials."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("gain-ray-gainraycompletion-countable-polynomial-avoidance"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.countable_polynomial_avoidance"),
                H("Simultaneous avoidance in a nonempty open domain"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Any countable family of nonzero real polynomials on a finite-dimensional real coordinate space is simultaneously nonzero at some point of every nonempty open set."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gain-ray-gainraycompletion-short-history-completion"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.short_history_completion"),
                H("Full-world completion of each generic prescribed history"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every d>=1, every countable eligible family s and every 1<=n<=d+1, there is a nonzero polynomial q_c for each pair. Every y outside their zero-set union has an original World d whose n initial pure-J reads equal y and at which every pair in s fails. The n=d+1 case retains no free gain coordinates."))), DescribeRole.Theorem),
Paragraph(Text("A Protocol fixes one countable palette of real matrices per word. Its deterministic decision function has the entire actual real history as input, and may select an action or stop with a palette member. No continuity, measurability, finite response alphabet or computability condition is imposed. Every action is one chronological M or J and has its immediate read; the initial identity read counts.")),
            Paragraph(Text("On the identical-row family, the pure-J history map H_n is the ordinary gain evaluation plus drift, independent of the row parameter. Its extension to the full coefficient-and-drift space is onto for n<=d+1. Therefore every nonzero exceptional-history polynomial has a nonzero polynomial pullback. The actual row worlds are selected afterwards in the open domain 0<theta<1 and beta nonzero.")),
            Paragraph(Text("Pairs whose words are pure J, including no actions, or have fewer than d+1 reads at and after their first M admit restricted polynomial success certificates. If their wedge polynomials were all zero, identical_row_annihilation would make their output zero on the entire row family. Together with the history pullbacks these certificates can be avoided simultaneously at one actual legal row world.")),
            Paragraph(Text("Follow the protocol on that world. A pure-J terminal word fails by its restricted certificate. If the first M is at clock n>d+1, the total bound 2(d+1) gives strictly fewer than d+1 suffix reads, so its restricted certificate applies. If the first M is at a clock 1<=n<=d+1, whole-world completion supplies another legal world with the same preceding pure-J history and with every eligible M-containing palette pair unsuccessful. Identical actual history forces the same preceding decisions and that next M. The uniform bound then supplies an actual terminal word containing this forced M, contradicting completion. Subsequent decisions need not match.")),
            Paragraph(Text("The upper protocol executes M exactly 2(d+1) times and then stops. At each word its palette is a fixed singleton. On the reached terminal word its matrix is exactBetaReadout d, which returns beta with scalar one on every original whole-polynomial world. It takes exactly 2d+3 original consecutive reads. The threshold concerns gain rays in this fixed-matrix output model; it makes no numerical stability or physical resource claim.")),
            Describe.Lean(DescribeId.Create("gain-ray-gainrayadaptive-upperprotocol"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.upperProtocol"),
                H("A preassigned singleton-palette protocol"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("It selects M before the intended terminal length and stops at that length with the preassigned matrix. All choices are independent of data."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("gain-ray-gainrayadaptive-upper-protocol-correct"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.upper_protocol_correct"),
                H("Exact attained native upper bound"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every declared degree and every World d, the actual protocol reaches M repeated 2(d+1) times, terminates there after exactly 2d+3 reads and returns its original coefficient vector."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gain-ray-gainrayadaptive-adaptive-upper"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.adaptive_upper"),
                H("Uniform attainment on every original world"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("upperProtocol d is UniformlySuccessful with 2d+3 total reads. The output scale is one."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gain-ray-gainrayadaptive-history-pullback-nonzero"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.history_pullback_nonzero"),
                H("Nonzero pullback by the actual pure-J history map"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For n<=d+1, every nonzero polynomial in n history values remains nonzero after substitution of the original gain values plus drift. Surjectivity is proved on the full linear extension before restricting to legal row worlds."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gain-ray-gainrayadaptive-adaptive-lower"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.adaptive_lower"),
                H("Arbitrary-history adaptive impossibility"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every d>=1 and every Protocol d, UniformlySuccessful P (2d+2) is false. Arbitrary actual-history actions, stops and palette selectors and countable preassigned fixed matrices remain in scope."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gain-ray-gainrayadaptive-adaptive-threshold"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/GainRayAdaptive.adaptive_threshold"),
                H("Both halves of the sharp threshold"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every d>=1, no native Protocol succeeds uniformly in at most 2d+2 reads, and a native Protocol succeeds uniformly in 2d+3 reads."))), DescribeRole.Theorem))));
}
